1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.nio.charset.StandardCharsets;
13	import java.security.MessageDigest;
14	import java.security.NoSuchAlgorithmException;
15	import java.util.Collection;
16	import java.util.List;
17	import java.util.Locale;
18	
19	/**
20	 * Maps Owner & OwnerDto using Mapstruct
21	 */
22	@Mapper(uses = PetMapper.class)
23	public interface OwnerMapper {
24	
25	    @Mapping(target = "displayName",
26	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
27	    @Mapping(target = "initials",
28	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
29	            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
30	    @Mapping(target = "householdId", expression = "java(householdId(owner))")
31	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
32	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
33	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
34	    @Mapping(target = "locality", expression = "java(locality(owner))")
35	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
36	    OwnerDto toOwnerDto(Owner owner);
37	
38	    /**
39	     * Derives an owner's preferred contact channel: {@code "EMAIL"} when the owner has a non-blank
40	     * email, otherwise {@code "PHONE"}.
41	     *
42	     * @param owner the owner to derive the contact preference for
43	     * @return {@code "EMAIL"} when an email is present, otherwise {@code "PHONE"}
44	     */
45	    default String contactPreference(Owner owner) {
46	        String email = owner.getEmail();
47	        return (email != null && !email.isBlank()) ? "EMAIL" : "PHONE";
48	    }
49	
50	    /**
51	     * Derives an owner's locality from its city using a fixed city-to-region table
52	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), returning the
53	     * canonical region string or {@code "UNKNOWN"} when the city is not in the table.
54	     *
55	     * @param owner the owner to derive the locality for
56	     * @return the canonical region string, or {@code "UNKNOWN"}
57	     */
58	    default String locality(Owner owner) {
59	        String city = owner.getCity();
60	        if (city == null) {
61	            return "UNKNOWN";
62	        }
63	        return switch (city) {
64	            case "Sydney" -> "NSW";
65	            case "Melbourne" -> "VIC";
66	            case "Brisbane" -> "QLD";
67	            default -> "UNKNOWN";
68	        };
69	    }
70	
71	    /**
72	     * Derives an owner's numeric membership level, fixed at creation. Starts at {@code 1}, plus
73	     * {@code 1} when an email is present (non-blank), plus {@code 1} when the owner's namesake count
74	     * is {@code 0}, capped at {@code 3} (level {@code 4} is reserved for tenure).
75	     *
76	     * @param owner the owner to derive the membership level for
77	     * @return the membership level, between {@code 1} and {@code 3}
78	     */
79	    default Integer membershipLevel(Owner owner) {
80	        int level = 1;
81	        String email = owner.getEmail();
82	        if (email != null && !email.isBlank()) {
83	            level++;
84	        }
85	        Integer namesakeCount = owner.getNamesakeCount();
86	        if (namesakeCount != null && namesakeCount == 0) {
87	            level++;
88	        }
89	        return Math.min(level, 3);
90	    }
91	
92	    /**
93	     * Derives an owner's membership number, formatted {@code <customerCode>-M<YY>} where
94	     * {@code <customerCode>} is the owner's customer code and {@code YY} is the last two digits
95	     * (zero-padded) of the owner's registration date year (e.g. {@code LON-SMI-0007-M26}).
96	     *
97	     * @param owner the owner to derive the membership number for
98	     * @return the formatted membership number
99	     */
100	    default String membershipNumber(Owner owner) {
101	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
102	        return owner.getCustomerCode() + "-M" + yy;
103	    }
104	
105	    /**
106	     * Derives an owner's household identifier: a stable value shared by every owner with the same
107	     * last name and address (compared case-insensitively with collapsed whitespace). Because it is
108	     * derived deterministically from those fields, owners created via the {@code sharesHousehold}
109	     * flag - which by definition have a matching last name and address - receive the same value.
110	     *
111	     * @param owner the owner to derive the household identifier for
112	     * @return a {@code HH-} prefixed identifier, never blank
113	     */
114	    default String householdId(Owner owner) {
115	        String key = normalizeHouseholdField(owner.getLastName()) + ' '
116	            + normalizeHouseholdField(owner.getAddress());
117	        try {
118	            byte[] digest = MessageDigest.getInstance("SHA-256")
119	                .digest(key.getBytes(StandardCharsets.UTF_8));
120	            StringBuilder sb = new StringBuilder("HH-");
121	            for (int i = 0; i < 6; i++) {
122	                sb.append(String.format("%02X", digest[i]));
123	            }
124	            return sb.toString();
125	        }
126	        catch (NoSuchAlgorithmException ex) {
127	            throw new IllegalStateException("SHA-256 not available", ex);
128	        }
129	    }
130	
131	    /**
132	     * Derives an owner's identity key, into which all duplicate detection is consolidated. The key
133	     * is {@code <normalizedTelephone>|<email or empty>|<householdId>}: the owner's (already E.164
134	     * normalized) telephone, its (already lower-cased) email or the empty string when none is held,
135	     * and its {@link #householdId(Owner) household id}. Two owners are duplicates only when their
136	     * whole identity keys are equal; because the telephone is part of the key, household members with
137	     * different telephones have different keys.
138	     *
139	     * @param owner the owner to derive the identity key for
140	     * @return the {@code telephone|email|householdId} identity key
141	     */
142	    default String identityKey(Owner owner) {
143	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
144	        String email = owner.getEmail() == null ? "" : owner.getEmail();
145	        return telephone + '|' + email + '|' + householdId(owner);
146	    }
147	
148	    /**
149	     * Collapses surrounding and internal whitespace and lower-cases a value so household fields can
150	     * be compared case-insensitively with collapsed whitespace. A {@code null} value normalizes to
151	     * the empty string. Mirrors the normalization used when enforcing the household rule on create.
152	     *
153	     * <p>Declared {@code private} so MapStruct does not treat it as an implicit String-to-String
154	     * conversion and apply it to unrelated String properties (last name, address, ...).
155	     */
156	    private String normalizeHouseholdField(String value) {
157	        if (value == null) {
158	            return "";
159	        }
160	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
161	    }
162	
163	    Owner toOwner(OwnerDto ownerDto);
164	
165	    @Mapping(target = "id", ignore = true)
166	    @Mapping(target = "pets", ignore = true)
167	    Owner toOwner(OwnerFieldsDto ownerDto);
168	
169	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
170	
171	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
172	
173	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
174	        OwnerPageDto ownerPageDto = new OwnerPageDto();
175	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
176	        ownerPageDto.setPage(ownerPage.getNumber());
177	        ownerPageDto.setSize(ownerPage.getSize());
178	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
179	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
180	        return ownerPageDto;
181	    }
182	}
