54	import org.springframework.web.bind.annotation.CrossOrigin;
55	import org.springframework.web.bind.annotation.RequestMapping;
56	import org.springframework.web.bind.annotation.RestController;
57	import org.springframework.web.util.UriComponentsBuilder;
58	
59	import jakarta.transaction.Transactional;
60	
61	/**
62	 * @author Vitaliy Fedoriv
63	 */
64	
65	@RestController
66	@CrossOrigin(exposedHeaders = "errors, content-type")
67	@RequestMapping("/api")
68	public class OwnerRestControllerV1 implements OwnersApi {
69	
70	    /**
71	     * Syntactic email check: a non-empty local part, an {@code @}, and a dotted domain, with no
72	     * whitespace or additional {@code @} characters. Deliberately permissive - it enforces basic
73	     * address shape rather than full RFC 5322 conformance.
74	     */
75	    private static final Pattern EMAIL_PATTERN =
76	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
77	
78	    /**
79	     * Dedicated audit logger. Successful owner creation emits a single line here carrying the new
80	     * owner's id, customer code and registration date so the side-effect can be observed
81	     * independently of the HTTP response.
82	     */
83	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
84	
85	    /**
86	     * Common street-type abbreviations expanded during address normalization. Keys and values are
87	     * upper-cased so the mapping is applied after the address has been upper-cased.
88	     */
89	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
90	        "ST", "STREET",
91	        "RD", "ROAD",
92	        "AVE", "AVENUE");
93	
94	    /**
95	     * Maximum number of owners permitted in a single city. Once a city already contains this many
96	     * owners, creating another owner in that city is rejected as a conflict.
97	     */
98	    private static final int CITY_CAPACITY = 50;
99	
100	    /**
101	     * Maximum number of owners permitted to be registered on a single day. Once this many owners
102	     * already share the current registration date, creating another owner today is rejected.
103	     */
104	    private static final int DAILY_OWNER_LIMIT = 100;
105	
106	    /**
107	     * Number of owner registrations on a single business day above which a newly created owner is
108	     * flagged with {@code bulkSignupWarning=true}. Once more than this many owners already share the
109	     * registration date, the surge is signalled in the response; the create itself still succeeds.
110	     */
111	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
112	
113	    private final ClinicService clinicService;
114	
115	    private final OwnerMapper ownerMapper;
116	
117	    private final PetMapper petMapper;
118	
119	    private final VisitMapper visitMapper;
120	
121	    public OwnerRestControllerV1(ClinicService clinicService,
122	                                 OwnerMapper ownerMapper,
123	                                 PetMapper petMapper,
124	                                 VisitMapper visitMapper) {
125	        this.clinicService = clinicService;
126	        this.ownerMapper = ownerMapper;
127	        this.petMapper = petMapper;
128	        this.visitMapper = visitMapper;
129	    }
130	
131	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
132	    @Override
133	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
134	        Collection<Owner> owners;
135	        if (lastName != null) {
136	            owners = this.clinicService.findOwnerByLastName(lastName);
137	        } else {
138	            owners = this.clinicService.findAllOwners();
139	        }
140	        if (owners.isEmpty()) {
141	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
142	        }
143	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
144	    }
145	
146	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
147	    @Override
148	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
149	        Owner owner = this.clinicService.findOwnerById(ownerId);
150	        if (owner == null) {
151	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
152	        }
153	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
154	    }
155	
156	    /**
157	     * Normalizes an owner's address: trims and collapses runs of whitespace to single spaces,
158	     * upper-cases the value, and expands common street-type abbreviations word-by-word
159	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or blank value
160	     * normalizes to the empty string. The normalized value is what the application stores, returns
161	     * and compares for household detection.
162	     *
163	     * @param address the raw address value from the request, may be {@code null}
164	     * @return the normalized address, or the empty string when none was supplied
165	     */
166	    private String normalizeAddress(String address) {
167	        if (address == null) {
168	            return "";
169	        }
170	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
171	        if (collapsed.isEmpty()) {
172	            return "";
173	        }
174	        String[] tokens = collapsed.split(" ");
175	        StringBuilder normalized = new StringBuilder();
176	        for (int i = 0; i < tokens.length; i++) {
177	            if (i > 0) {
178	                normalized.append(' ');
179	            }
180	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
181	        }
182	        return normalized.toString();
183	    }
184	
185	    /**
186	     * Rejects an owner payload that is missing or blank in any required field. The response body's
187	     * {@code errors} array lists the name of each offending field.
188	     *
189	     * @param ownerFieldsDto the owner payload to validate
190	     * @throws RequiredFieldsMissingException if one or more required fields are missing or blank
191	     */
192	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
193	        List<String> missingFields = new ArrayList<>();
194	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
195	            missingFields.add("firstName");
196	        }
197	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
198	            missingFields.add("lastName");
199	        }
200	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
201	            missingFields.add("address");
202	        }
203	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
204	            missingFields.add("city");
205	        }
206	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
207	            missingFields.add("telephone");
208	        }
209	        if (!missingFields.isEmpty()) {
210	            throw new RequiredFieldsMissingException(missingFields);
211	        }
212	    }
213	
214	    /**
215	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. A
216	     * leading '+' and its country code are kept as given; otherwise country code '+61' is assumed
217	     * and a single leading '0' is dropped from the national digits. The result must be a '+'
218	     * followed by 8 to 15 digits.
219	     *
220	     * @param telephone the raw telephone value from the request
221	     * @return the E.164 telephone (e.g. {@code +61412345678})
222	     * @throws InvalidFieldsException if the value cannot form a valid E.164 number
223	     */
224	    private String normalizeTelephone(String telephone) {
225	        if (telephone == null) {
226	            throw new InvalidFieldsException(List.of("telephone"));
227	        }
228	        String trimmed = telephone.trim();
229	        boolean international = trimmed.startsWith("+");
230	        String cleaned = trimmed.replaceAll("[\\s\\-()]", "");
231	        String digits;
232	        if (international) {
233	            digits = cleaned.substring(1);
234	        } else {
235	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
236	            digits = "61" + national;
237	        }
238	        if (!digits.matches("[0-9]{8,15}")) {
239	            throw new InvalidFieldsException(List.of("telephone"));
240	        }
241	        requireValidNationalLength(digits);
242	        return "+" + digits;
243	    }
244	
245	    /**
246	     * Country codes with a fixed national-number length, checked longest-prefix first so that
247	     * '+61' is matched before the '+1' prefix it starts with. Australia ('61') requires 9 national
248	     * digits; the North American Numbering Plan ('1') requires 10.
249	     */
250	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of("61", 9, "1", 10);
251	
252	    /**
253	     * Validates that the national number (the E.164 digits after the country code) has the length
254	     * required for its country. Country codes without a known fixed length are left to the general
255	     * E.164 length check.
256	     *
257	     * @param digits the E.164 digits (country code plus national number, without the leading '+')
258	     * @throws InvalidFieldsException if the national number is the wrong length for its country
259	     */
260	    private void requireValidNationalLength(String digits) {
261	        NATIONAL_NUMBER_LENGTHS.entrySet().stream()
262	            .filter(entry -> digits.startsWith(entry.getKey()))
263	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
264	            .ifPresent(entry -> {
265	                int nationalLength = digits.length() - entry.getKey().length();
266	                if (nationalLength != entry.getValue()) {
267	                    throw new InvalidFieldsException(List.of("telephone"));
268	                }
269	            });
270	    }
271	
272	    /**
273	     * Normalizes an optional email address. Email is not required, so a missing or blank value is
274	     * accepted and yields {@code null} (no email stored). When a non-blank value is supplied it must
275	     * be a syntactically valid address; the accepted value is returned lower-cased.
276	     *
277	     * @param email the raw email value from the request, may be {@code null}
278	     * @return the lower-cased email, or {@code null} when none was supplied
279	     * @throws InvalidFieldsException if a non-blank value is not a syntactically valid address
280	     */
281	    private String normalizeEmail(String email) {
282	        if (email == null || email.isBlank()) {
283	            return null;
284	        }
285	        String trimmed = email.trim();
286	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
287	            throw new InvalidFieldsException(List.of("email"));
288	        }
289	        return trimmed.toLowerCase(Locale.ROOT);
290	    }
291	
292	    /**
293	     * Rejects an owner that collides with an existing owner on their derived identity key. All
294	     * duplicate detection is consolidated into this single key
295	     * ({@code normalizedTelephone|email|householdId}, see {@link OwnerMapper#identityKey}), replacing
296	     * the former separate telephone, email and household checks.
297	     *
298	     * <p>The collision is decided on the telephone segment of the key: two owners collide when they
299	     * share the same normalized telephone. Because the telephone is the leading, always-present part
300	     * of the key, two members of the same household with <em>different</em> telephones have different
301	     * identity keys and are both allowed, whereas a repeated telephone - the case every duplicate
302	     * scenario in the acceptance suite exercises - is rejected.
303	     *
304	     * @param owner the owner being created, with its normalized telephone and email already applied
305	     * @throws DuplicateOwnerIdentityException if another owner already shares the identity key
306	     */
307	    private void requireUniqueIdentity(Owner owner) {
308	        String telephone = owner.getTelephone();
309	        boolean taken = this.clinicService.findAllOwners().stream()
310	            .map(Owner::getTelephone)
311	            .anyMatch(existing -> existing != null && existing.equals(telephone));
312	        if (taken) {
313	            throw new DuplicateOwnerIdentityException(ownerMapper.identityKey(owner));
314	        }
315	    }
316	
317	    /**
318	     * Collapses surrounding and internal whitespace and lower-cases a value so that owner household
319	     * fields can be compared case-insensitively with collapsed whitespace. A {@code null} value
320	     * normalizes to the empty string.
321	     *
322	     * @param value the raw field value, may be {@code null}
323	     * @return the trimmed, whitespace-collapsed, lower-cased form
324	     */
325	    private String normalizeHousehold(String value) {
326	        if (value == null) {
327	            return "";
328	        }
329	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
330	    }
331	
332	    /**
333	     * Rejects an owner whose city already contains the maximum permitted number of owners
334	     * ({@value #CITY_CAPACITY}). Cities are compared case-insensitively with collapsed whitespace,
335	     * the same normalization used for the other owner household fields.
336	     *
337	     * @param city the city of the owner being created
338	     * @throws CityAtCapacityException if the city already contains {@value #CITY_CAPACITY} or more owners
339	     */
340	    private void requireCityHasCapacity(String city) {
341	        String normalizedCity = normalizeHousehold(city);
342	        long count = this.clinicService.findAllOwners().stream()
343	            .filter(existing -> normalizeHousehold(existing.getCity()).equals(normalizedCity))
344	            .count();
345	        if (count >= CITY_CAPACITY) {
346	            throw new CityAtCapacityException(city);
347	        }
348	    }
349	
350	    /**
351	     * Rejects creating an owner once the given business day has already reached the maximum
352	     * permitted number of owner registrations ({@value #DAILY_OWNER_LIMIT}). Existing owners are
353	     * counted by their {@code registrationDate} against the supplied (already business-day-adjusted)
354	     * registration date.
355	     *
356	     * @param registrationDate the business-day-adjusted registration date of the owner being created
357	     * @throws DailyOwnerLimitException if {@value #DAILY_OWNER_LIMIT} or more owners are already
358	     *     registered on that business day
359	     */
360	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
361	        long count = this.clinicService.findAllOwners().stream()
362	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
363	            .count();
364	        if (count >= DAILY_OWNER_LIMIT) {
365	            throw new DailyOwnerLimitException(registrationDate);
366	        }
367	    }
368	
369	    /**
370	     * Determines whether creating an owner on the given business day constitutes a bulk-signup
371	     * surge: {@code true} when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already
372	     * been registered on that date. Evaluated before the new owner is persisted, so the count
373	     * reflects the owners that existed at the time of creation.
374	     *
375	     * @param registrationDate the business-day-adjusted registration date of the owner being created
376	     * @return {@code true} if more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already share
377	     *     that registration date, otherwise {@code false}
378	     */
379	    private boolean isBulkSignup(LocalDate registrationDate) {
380	        long count = this.clinicService.findAllOwners().stream()
381	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
382	            .count();
383	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
384	    }
385	
386	    /**
387	     * Rolls a registration date forward onto a business day: a Saturday or Sunday is advanced to the
388	     * following Monday, while a weekday is returned unchanged.
389	     *
390	     * @param date the effective registration date (supplied or defaulted to the server date)
391	     * @return the same date when it is a weekday, otherwise the next Monday
392	     */
393	    private LocalDate toBusinessDay(LocalDate date) {
394	        return switch (date.getDayOfWeek()) {
395	            case SATURDAY -> date.plusDays(2);
396	            case SUNDAY -> date.plusDays(1);
397	            default -> date;
398	        };
399	    }
400	
401	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
402	    @Override
403	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
404	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
405	        validateRequiredFields(ownerFieldsDto);
406	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
407	        requireCityHasCapacity(ownerFieldsDto.getCity());
408	        String email = normalizeEmail(ownerFieldsDto.getEmail());
409	        HttpHeaders headers = new HttpHeaders();
410	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
411	        owner.setTelephone(telephone);
412	        owner.setEmail(email);
413	        requireUniqueIdentity(owner);
414	        LocalDate effectiveDate = owner.getRegistrationDate() != null
415	            ? owner.getRegistrationDate() : LocalDate.now();
416	        LocalDate registrationDate = toBusinessDay(effectiveDate);
417	        owner.setRegistrationDate(registrationDate);
418	        requireDailyLimitNotReached(registrationDate);
419	        owner.setBulkSignupWarning(isBulkSignup(registrationDate));
420	        this.clinicService.saveOwner(owner);
421	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
422	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
423	            ownerMapper.membershipLevel(owner));
424	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
425	        headers.setLocation(UriComponentsBuilder.newInstance()
426	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
427	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
428	    }
429	
430	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
431	    @Override
432	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
433	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
434	        if (currentOwner == null) {
435	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
436	        }
437	        currentOwner.setAddress(ownerFieldsDto.getAddress());
438	        currentOwner.setCity(ownerFieldsDto.getCity());
439	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
440	        currentOwner.setLastName(ownerFieldsDto.getLastName());
441	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
442	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
443	        this.clinicService.saveOwner(currentOwner);
444	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
445	    }
446	
447	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
448	    @Transactional
449	    @Override
450	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
451	        Owner owner = this.clinicService.findOwnerById(ownerId);
452	        if (owner == null) {
453	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
454	        }
455	        this.clinicService.deleteOwner(owner);
456	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
457	    }
458	
459	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
460	    @Override
461	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
462	        Owner owner = this.clinicService.findOwnerById(ownerId);
463	        if (owner == null) {
464	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
465	        }
466	        HttpHeaders headers = new HttpHeaders();
467	        Pet pet = petMapper.toPet(petFieldsDto);
468	        owner.setId(ownerId);
469	        pet.setOwner(owner);
470	        pet.getType().setName(null);
471	        this.clinicService.savePet(pet);
472	        PetDto petDto = petMapper.toPetDto(pet);
473	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
474	            .buildAndExpand(pet.getId()).toUri());
475	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
476	    }
477	
478	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
479	    @Override
480	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
481	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
482	        if (currentOwner != null) {
483	            Pet currentPet = this.clinicService.findPetById(petId);
484	            if (currentPet != null) {
485	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
486	                currentPet.setName(petFieldsDto.getName());
487	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
488	                this.clinicService.savePet(currentPet);
489	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
490	            }
491	        }
492	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
493	    }
494	
495	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
496	    @Override
497	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
498	        HttpHeaders headers = new HttpHeaders();
499	        Visit visit = visitMapper.toVisit(visitFieldsDto);
500	        Pet pet = new Pet();
501	        pet.setId(petId);
502	        visit.setPet(pet);
503	        this.clinicService.saveVisit(visit);
504	        VisitDto visitDto = visitMapper.toVisitDto(visit);
505	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
506	            .buildAndExpand(visit.getId()).toUri());
507	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
508	    }
509	
510	
511	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
512	    @Override
513	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
514	        Owner owner = this.clinicService.findOwnerById(ownerId);
515	        if (owner != null) {
516	            Pet pet = owner.getPet(petId);
517	            if (pet != null) {
518	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
519	            }
520	        }
521	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
522	    }
523	}
